function onInit(self, engine) {
  if (typeof self.started !== 'boolean') self.started = false;
  if (typeof self.completed !== 'boolean') self.completed = false;
  var manager = engine.uiManager || (typeof KozUIManager !== 'undefined' ? KozUIManager : null) || (typeof uiManager !== 'undefined' ? uiManager : null);
  if (!manager) return;
  manager.registerScreen(self.id + '_menu', {
    layer: 'hud',
    layerOrder: 100,
    isVisible: function() { return !self.started; },
    create: function() {
      var wrap = document.createElement('div');
      wrap.style.cssText = 'position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:radial-gradient(circle at top, rgba(249,115,22,0.18), rgba(2,6,23,0.95));pointer-events:auto;font-family:Trebuchet MS,sans-serif;';
      var card = document.createElement('div');
      card.style.cssText = 'width:min(560px,92vw);padding:28px 26px;border-radius:18px;background:rgba(15,23,42,0.96);border:1px solid rgba(148,163,184,0.25);box-shadow:0 24px 80px rgba(0,0,0,0.45);color:#e2e8f0;';
      var title = document.createElement('h1');
      title.textContent = props.title || 'Koz Template';
      title.style.cssText = 'margin:0 0 8px;font-size:34px;';
      var subtitle = document.createElement('p');
      subtitle.textContent = props.subtitle || '';
      subtitle.style.cssText = 'margin:0 0 14px;color:#94a3b8;line-height:1.4;';
      var instructions = document.createElement('p');
      instructions.textContent = props.instructions || '';
      instructions.style.cssText = 'margin:0 0 18px;color:#cbd5e1;line-height:1.5;';
      var button = document.createElement('button');
      button.textContent = props.actionLabel || 'Start';
      button.style.cssText = 'padding:12px 18px;border:none;border-radius:999px;background:#fb923c;color:#431407;font-weight:700;cursor:pointer;';
      button.onclick = function() {
        self.started = true;
        self.completed = false;
        var manager = (engine && engine.sceneManager) || (typeof sceneManager !== 'undefined' ? sceneManager : null) || window.sceneManager;
        if (props.nextSceneId && manager && typeof manager.loadScene === 'function') {
          window.__kozPendingAutoStart = true;
          manager.loadScene(props.nextSceneId);
          return;
        }
        if (typeof self.onStartGame === 'function') self.onStartGame();
      };
      var note = document.createElement('p');
      note.textContent = props.note || '';
      note.style.cssText = 'margin:14px 0 0;color:#64748b;font-size:12px;line-height:1.5;';
      card.appendChild(title);
      if (subtitle.textContent) card.appendChild(subtitle);
      if (instructions.textContent) card.appendChild(instructions);
      card.appendChild(button);
      if (note.textContent) card.appendChild(note);
      wrap.appendChild(card);
      return wrap;
    }
  });
}

function onUpdate(self, engine, dt) {
  if (!self.started && !props.nextSceneId && window.__kozPendingAutoStart && typeof self.onStartGame === 'function') {
    window.__kozPendingAutoStart = false;
    self.started = true;
    self.completed = false;
    self.onStartGame();
  }
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function mapAt(engine, x, y) {
  if (!engine || !engine.world || typeof engine.world.isSolidCell !== 'function') return 1;
  return engine.world.isSolidCell(Math.floor(x), Math.floor(y)) ? 1 : 0;
}

function syncCamera(self, engine) {
  if (!engine || !engine.renderer3d || !engine.renderer3d.isEnabled()) return;
  var cellSize = (engine.world && engine.world.cellSize) || 24;
  engine.renderer3d.setOptions({
    wallHeight: cellSize * 2.25,
    clearColor: '#07111d',
    floorColor: '#111827',
    ceilingColor: '#1e3a5f',
    wallColor: '#fb923c'
  });
  engine.renderer3d.setCamera({
    x: self.x * cellSize,
    y: cellSize * 0.72,
    z: self.y * cellSize,
    yaw: self.yaw,
    pitch: self.pitch,
    fov: 74
  });
}

function drawMiniMap(self, engine) {
  if (!self.mapCanvas || !engine || !engine.world) return;
  var canvas = self.mapCanvas;
  var ctx = canvas.getContext('2d');
  if (!ctx) return;
  var world = engine.world;
  var cols = world.cols || 0;
  var rows = world.rows || 0;
  if (!cols || !rows) return;
  var maxSize = 132;
  var scale = Math.max(8, Math.floor(Math.min(maxSize / cols, maxSize / rows)));
  canvas.width = cols * scale;
  canvas.height = rows * scale;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (var y = 0; y < rows; y += 1) {
    for (var x = 0; x < cols; x += 1) {
      var cellX = world.offsetX + x;
      var cellY = world.offsetY + y;
      ctx.fillStyle = world.isSolidCell(cellX, cellY) ? '#475569' : 'rgba(15,23,42,0.9)';
      ctx.fillRect(x * scale, y * scale, scale - 1, scale - 1);
    }
  }
  ctx.fillStyle = self.completed ? '#22c55e' : '#fb923c';
  ctx.beginPath();
  ctx.arc((self.x - world.offsetX) * scale, (self.y - world.offsetY) * scale, Math.max(3, scale * 0.18), 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = '#fdba74';
  ctx.lineWidth = Math.max(1.5, scale * 0.12);
  ctx.beginPath();
  ctx.moveTo((self.x - world.offsetX) * scale, (self.y - world.offsetY) * scale);
  ctx.lineTo((self.x - world.offsetX + Math.cos(self.yaw) * 0.9) * scale, (self.y - world.offsetY + Math.sin(self.yaw) * 0.9) * scale);
  ctx.stroke();
}

function onInit(self, engine) {
  self.x = 1.5;
  self.y = 1.5;
  self.yaw = 0;
  self.pitch = -0.08;
  self.completed = false;
  self.onStartGame = function() {
    self.x = 1.5;
    self.y = 1.5;
    self.yaw = 0;
    self.pitch = -0.08;
    self.completed = false;
    syncCamera(self, engine);
    if (engine && engine.renderer3d) engine.renderer3d.requestPointerLock();
  };

  if (window.__kozFpsMouseMoveHandler) {
    window.removeEventListener('mousemove', window.__kozFpsMouseMoveHandler);
  }
  window.__kozFpsMouseMoveHandler = function(event) {
    if (!self.started) return;
    self.yaw += (event.movementX || 0) * 0.0035;
    self.pitch = clamp(self.pitch - (event.movementY || 0) * 0.0022, -0.75, 0.75);
    syncCamera(self, engine);
  };
  window.addEventListener('mousemove', window.__kozFpsMouseMoveHandler);

  syncCamera(self, engine);

  var manager = engine.uiManager || (typeof KozUIManager !== 'undefined' ? KozUIManager : null) || (typeof uiManager !== 'undefined' ? uiManager : null);
  if (!manager) return;
  manager.registerScreen(self.id + '_fps_hud', {
    layer: 'hud',
    layerOrder: 5,
    isVisible: function() { return true; },
    create: function() {
      var wrap = document.createElement('div');
      wrap.style.cssText = 'position:absolute;inset:0;pointer-events:none;font-family:Trebuchet MS,sans-serif;';
      var crosshair = document.createElement('div');
      crosshair.id = self.id + '_crosshair';
      crosshair.textContent = '+';
      crosshair.style.cssText = 'position:absolute;left:50%;top:50%;transform:translate(-50%,-54%);font-size:26px;line-height:1;color:rgba(255,255,255,0.82);text-shadow:0 0 12px rgba(2,6,23,0.9);';
      var label = document.createElement('div');
      label.id = self.id + '_label';
      label.style.cssText = 'position:absolute;right:16px;top:16px;padding:12px 14px;border-radius:14px;background:rgba(15,23,42,0.76);color:#e2e8f0;line-height:1.4;';
      var map = document.createElement('canvas');
      map.id = self.id + '_map';
      map.style.cssText = 'position:absolute;left:16px;bottom:16px;width:132px;height:132px;padding:8px;border-radius:16px;background:rgba(15,23,42,0.76);box-shadow:0 18px 60px rgba(2,6,23,0.45);';
      wrap.appendChild(crosshair);
      wrap.appendChild(label);
      wrap.appendChild(map);
      self.mapCanvas = map;
      return wrap;
    },
    update: function() {
      var label = document.getElementById(self.id + '_label');
      var crosshair = document.getElementById(self.id + '_crosshair');
      if (label) {
        label.innerHTML = 'WebGL FPS prototype<br/>' +
          (self.started ? 'WASD move, mouse look, Q/E turn' : 'Press Start on the menu overlay') +
          '<br/>Grid ' + self.x.toFixed(2) + ', ' + self.y.toFixed(2) +
          (self.completed ? '<br/>Exit reached' : '');
      }
      if (crosshair) crosshair.style.opacity = self.started ? '1' : '0.25';
      drawMiniMap(self, engine);
    }
  });
}

function onUpdate(self, engine, dt) {
  if (!self.started) {
    syncCamera(self, engine);
    return;
  }

  var forward = 0;
  var strafe = 0;
  if (keyIsDown(87) || keyIsDown(UP_ARROW)) forward += 1;
  if (keyIsDown(83) || keyIsDown(DOWN_ARROW)) forward -= 1;
  if (keyIsDown(65) || keyIsDown(LEFT_ARROW)) strafe -= 1;
  if (keyIsDown(68) || keyIsDown(RIGHT_ARROW)) strafe += 1;
  if (keyIsDown(81)) self.yaw -= 1.8 * dt;
  if (keyIsDown(69)) self.yaw += 1.8 * dt;

  var speed = 2.8;
  var moveX = Math.cos(self.yaw) * forward + Math.cos(self.yaw + Math.PI * 0.5) * strafe;
  var moveY = Math.sin(self.yaw) * forward + Math.sin(self.yaw + Math.PI * 0.5) * strafe;
  var nextX = self.x + moveX * speed * dt;
  var nextY = self.y + moveY * speed * dt;
  if (!mapAt(engine, nextX, self.y)) self.x = nextX;
  if (!mapAt(engine, self.x, nextY)) self.y = nextY;

  if (self.x > 9.2 && self.y > 8.2) {
    self.completed = true;
    self.started = false;
    if (engine && engine.renderer3d) engine.renderer3d.exitPointerLock();
  }

  syncCamera(self, engine);
}
